"""v2.1: more slow cooker, Instant Pot, air fryer and 30-minute recipes."""
import lib
from v21lib import R
SC, IPF, AF, Q = "87-v21-slow-cooker.txt", "88-v21-instant-pot.txt", "89-v21-air-fryer.txt", "90-v21-30-minute.txt"

# ---- slow cooker: protein x sauce ----
PROT = {  # name, ingredient, low hours, prep note
    "Chicken Thighs": ("1 kg|chicken thighs, boneless and skinless", 5, "Shred or slice the chicken in the sauce"),
    "Pork Shoulder": ("1.5 kg|pork shoulder, boneless, cut into 4 pieces", 8, "Shred the pork with two forks and stir it back into the sauce"),
    "Beef Chuck": ("1.2 kg|beef chuck, cut into 4 cm chunks", 8, "The beef should fall apart when pressed; break it up a little"),
    "Lamb Shoulder": ("1.2 kg|lamb shoulder, boneless, cut into 4 cm chunks", 7, "Skim any fat from the top and break the lamb up a little"),
    "Chickpea": ("800 g|chickpeas, cooked and drained", 4, "Mash a few chickpeas against the side to thicken the sauce"),
}
SAUCE = {  # title pattern, cuisine, sauce ingredients, liquid, finish
    "salsa verde": ("Slow Cooker Salsa Verde %s", "Mexican", "450 g|salsa verde; 1|onion, chopped; 1 tsp|cumin; 2|garlic cloves, crushed", "", "1 handful|coriander, chopped; 1|lime, juiced", ["Chicken Thighs", "Pork Shoulder", "Chickpea"]),
    "bbq": ("Slow Cooker Smoky BBQ %s", "American", "250 ml|barbecue sauce; 1|onion, sliced; 1 tbsp|smoked paprika; 2 tbsp|cider vinegar", "", "", ["Chicken Thighs", "Pork Shoulder", "Beef Chuck"]),
    "korma": ("Slow Cooker Coconut Korma %s", "Indian", "400 ml|coconut milk; 3 tbsp|korma paste; 1|onion, chopped; 2 tbsp|ground almonds", "", "1 handful|coriander, chopped", ["Chicken Thighs", "Lamb Shoulder", "Chickpea"]),
    "tagine": ("Slow Cooker Apricot Tagine with %s", "Moroccan", "400 g|chopped tomatoes; 100 g|dried apricots; 1|onion, chopped; 2 tsp|ras el hanout; 1|cinnamon stick", "250 ml|chicken stock", "1 handful|parsley, chopped; 2 tbsp|sliced almonds, toasted", ["Chicken Thighs", "Lamb Shoulder", "Chickpea", "Beef Chuck"]),
    "ragu": ("Slow Cooker Red Wine-Free %s Ragù", "Italian", "800 g|chopped tomatoes; 1|onion, chopped; 1|carrot, chopped; 2|garlic cloves, crushed; 2 tbsp|tomato paste; 1 tsp|dried oregano", "200 ml|beef stock", "30 g|parmesan, grated", ["Beef Chuck", "Pork Shoulder", "Lamb Shoulder"]),
    "adobo": ("Slow Cooker Filipino-Style %s Adobo", "Filipino", "120 ml|soy sauce; 120 ml|cider vinegar; 6|garlic cloves, crushed; 3|bay leaves; 1 tsp|black peppercorns; 1 tbsp|brown sugar", "", "2|spring onions, sliced", ["Chicken Thighs", "Pork Shoulder"]),
    "goulash": ("Slow Cooker Paprika %s Goulash", "Hungarian", "2|onions, sliced; 2 tbsp|sweet paprika; 1|red bell pepper, sliced; 400 g|chopped tomatoes; 1 tsp|caraway seeds", "250 ml|beef stock", "4 tbsp|sour cream", ["Beef Chuck", "Pork Shoulder", "Chickpea"]),
    "chipotle": ("Slow Cooker Chipotle %s", "Mexican", "2 tbsp|chipotle peppers in adobo, chopped; 400 g|chopped tomatoes; 1|onion, chopped; 1 tsp|cumin; 1 tsp|dried oregano", "", "1|lime, juiced; 1 handful|coriander, chopped", ["Chicken Thighs", "Beef Chuck", "Pork Shoulder"]),
    "rendang": ("Slow Cooker Rendang-Style %s", "Indonesian", "400 ml|coconut milk; 4 tbsp|curry paste (rendang); 2|lemongrass stalks, bruised; 4|kaffir lime leaves; 1 tbsp|brown sugar", "", "", ["Beef Chuck", "Chicken Thighs", "Lamb Shoulder"]),
    "honey mustard": ("Slow Cooker Honey Mustard %s", "American", "4 tbsp|dijon mustard; 4 tbsp|honey; 1|onion, sliced; 2|garlic cloves, crushed", "150 ml|chicken stock", "1 tbsp|parsley, chopped", ["Chicken Thighs", "Pork Shoulder"]),
    "jerk": ("Slow Cooker Jerk %s", "Jamaican", "4 tbsp|jerk seasoning; 1|onion, sliced; 2 tbsp|brown sugar; 2|limes, juiced", "150 ml|chicken stock", "2|spring onions, sliced", ["Chicken Thighs", "Pork Shoulder"]),
    "mediterranean": ("Slow Cooker Lemon Olive %s", "Greek", "2|lemons, zest and juice; 100 g|kalamata olives; 1|onion, sliced; 4|garlic cloves, sliced; 1 tbsp|dried oregano", "200 ml|chicken stock", "1 handful|parsley, chopped", ["Chicken Thighs", "Lamb Shoulder", "Chickpea"]),
    "massaman": ("Slow Cooker Massaman %s with Potatoes", "Thai", "400 ml|coconut milk; 3 tbsp|massaman curry paste; 400 g|potatoes, cubed; 1|onion, chopped; 2 tbsp|peanuts; 1 tbsp|fish sauce", "", "", ["Beef Chuck", "Chicken Thighs", "Chickpea"]),
}
for key, (pat, cu, sauce, liquid, finish, prots) in SAUCE.items():
    for p in prots:
        ing, hours, note = PROT[p]
        if p == "Chickpea" and "fish sauce" in sauce: sauce2 = sauce.replace("1 tbsp|fish sauce", "1 tbsp|soy sauce")
        else: sauce2 = sauce
        liq = liquid
        if p == "Chickpea" and liq: liq = liq.replace("chicken stock", "vegetable stock").replace("beef stock", "vegetable stock")
        pn = p if p != "Chickpea" else "Chickpeas"
        t = pat % pn
        ings = ing + "; 1 tsp|salt; " + sauce2 + ("; " + liq if liq else "") + ("; " + finish if finish else "")
        steps = ["Put the " + pn.lower() + " in the slow cooker and season with the salt",
                 "Mix in the sauce ingredients" + (" and the stock" if liq else "") + ", turning everything to coat",
                 "Cover and cook on Low for %d hours (or High for about %d hours) until tender" % (hours, max(2, hours // 2)),
                 note + ". Taste for salt" + (" and finish with the " + ", ".join(x.split("|")[1].split(",")[0] for x in finish.split("; ")) if finish else "")]
        lib_title = t if len(t) <= 60 else t.replace("Slow Cooker ", "")
        R(SC, lib_title, "Main", cu, 15, hours * 60, 6 if p != "Chickpea" else 4, "Dinner, Main dish", ings, steps)
for t, cu, ings, hrs, st in [
    ("Slow Cooker Lentil and Sweet Potato Stew", "International", "300 g|red lentils; 2|sweet potatoes, cubed; 1|onion, chopped; 400 g|chopped tomatoes; 1 l|vegetable stock; 2 tsp|curry powder; 100 g|spinach", 6, "Put everything except the spinach in the slow cooker / Cover and cook on Low for 6 hours / Stir in the spinach until wilted and season"),
    ("Slow Cooker French Onion Soup", "French", "1.2 kg|onions, thinly sliced; 50 g|butter; 1 tsp|sugar; 1.2 l|beef stock; 2 sprigs|thyme; 4 slices|baguette; 100 g|gruyere, grated", 10, "Put the onions, butter and sugar in the slow cooker. Cover and cook on High for 8 hours, stirring once or twice, until deep golden / Add the stock and thyme and cook on High for 1 to 2 hours more / Ladle into bowls, top with the bread and cheese and grill until bubbling"),
    ("Slow Cooker Split Pea Soup", "American", "500 g|split peas, rinsed; 1|onion, chopped; 2|carrots, chopped; 2|celery stalks, chopped; 1.5 l|vegetable stock; 2|bay leaves", 8, "Put everything in the slow cooker / Cover and cook on Low for 8 hours until the peas fall apart / Remove the bay leaves, blend partly and season"),
    ("Slow Cooker Steel-Cut Oats", "American", "160 g|steel-cut oats; 1 l|water; 250 ml|milk; 1|apple, chopped; 1 tsp|cinnamon; 2 tbsp|maple syrup", 7, "Grease the slow cooker well and add everything with a pinch of salt / Cover and cook on Low for 7 hours, overnight / Stir well and loosen with a little milk"),
    ("Slow Cooker Pinto Beans", "Mexican", "500 g|dried pinto beans, rinsed; 1|onion, halved; 4|garlic cloves; 1 tsp|cumin; 2 l|water", 8, "Put the beans, onion, garlic, cumin and water in the slow cooker / Cover and cook on Low for 8 hours until creamy / Season with salt only at the end and discard the onion"),
    ("Slow Cooker Ratatouille", "French", "1|eggplant, cubed; 2|zucchini, cubed; 2|red bell peppers, chopped; 1|onion, chopped; 400 g|chopped tomatoes; 3|garlic cloves; 2 tbsp|olive oil; 1 tsp|dried thyme", 5, "Put everything in the slow cooker with 1 tsp salt and stir / Cover and cook on Low for 5 hours / Stir gently and drizzle with a little more oil"),
    ("Slow Cooker Mushroom Stroganoff", "Russian", "750 g|mushrooms, sliced; 1|onion, sliced; 3|garlic cloves; 2 tsp|paprika; 300 ml|vegetable stock; 150 ml|sour cream; 1 handful|parsley", 4, "Put the mushrooms, onion, garlic, paprika and stock in the slow cooker / Cover and cook on Low for 4 hours / Stir in the sour cream and parsley and season. Serve over noodles or rice"),
    ("Slow Cooker Turkey Chili", "Tex-Mex", "750 g|ground turkey; 800 g|kidney beans, drained; 800 g|chopped tomatoes; 1|onion, chopped; 2 tbsp|chili powder; 1 tsp|cumin; 1|red bell pepper, chopped", 6, "Brown the turkey in a pan and tip into the slow cooker / Add everything else with 1 tsp salt / Cover and cook on Low for 6 hours"),
    ("Slow Cooker Applesauce", "American", "1.5 kg|apples, peeled and chopped; 120 ml|water; 2 tbsp|lemon juice; 1 tsp|cinnamon; 2 tbsp|brown sugar|opt", 4, "Put everything in the slow cooker / Cover and cook on Low for 4 hours until very soft / Mash or blend"),
    ("Slow Cooker Baked Potatoes", "American", "4|baking potatoes; 1 tbsp|olive oil; 1 tsp|salt; 40 g|butter; 60 g|cheddar, grated|opt", 7, "Prick the potatoes, rub with oil and salt and wrap each in foil / Cook on Low for 7 to 8 hours until soft / Split and fill with butter and cheese"),
    ("Slow Cooker Chicken Noodle Soup", "American", "600 g|chicken thighs, boneless; 2|carrots, sliced; 2|celery stalks, sliced; 1|onion, chopped; 1.5 l|chicken stock; 150 g|egg noodles", 6, "Put the chicken, vegetables and stock in the slow cooker with 1 tsp salt / Cover and cook on Low for 6 hours. Shred the chicken / Add the noodles for the last 20 minutes on High"),
]:
    R(SC, t, "Soup" if "Soup" in t else ("Side" if t.endswith(("Beans", "Potatoes", "Applesauce")) else ("Breakfast" if "Oats" in t else "Main")), cu, 15, hrs * 60, 6, "Dinner, Main dish" if "Soup" not in t and "Oats" not in t else ("Breakfast" if "Oats" in t else "Lunch, Dinner, Soup"), ings, st)

