# ---- 30-minute meals: protein x sauce stir-fries and skillets ----
QP = [("Chicken", "500 g|chicken breasts, thinly sliced", 6), ("Beef", "450 g|beef sirloin, thinly sliced", 3), ("Shrimp", "400 g|shrimp, peeled", 3), ("Tofu", "400 g|firm tofu, pressed and cubed", 8), ("Pork", "450 g|pork tenderloin, thinly sliced", 5)]
QS = [("Black Pepper", "Chinese", "2 tbsp|oyster sauce; 1 tbsp|soy sauce; 1.5 tsp|black pepper, coarsely ground; 1|onion, sliced; 1|green bell pepper, sliced"),
      ("Honey Sesame", "Chinese-American", "3 tbsp|honey; 3 tbsp|soy sauce; 1 tbsp|sesame oil; 1 tbsp|sesame seeds; 200 g|broccoli, florets"),
      ("Garlic Ginger", "Chinese", "4|garlic cloves, sliced; 3 cm|ginger, cut into matchsticks; 2 tbsp|soy sauce; 1 tbsp|rice vinegar; 200 g|snap peas"),
      ("Thai Basil", "Thai", "4|garlic cloves, chopped; 2|red chilies, sliced; 2 tbsp|oyster sauce; 1 tbsp|fish sauce; 1 large handful|thai basil"),
      ("Lemongrass", "Vietnamese", "2|lemongrass stalks, finely chopped; 2|garlic cloves, chopped; 1 tbsp|fish sauce; 1 tbsp|brown sugar; 1|red onion, sliced"),
      ("Peanut", "Indonesian", "3 tbsp|peanut butter; 2 tbsp|soy sauce; 1|lime, juiced; 1 tbsp|sweet chili sauce; 1|red bell pepper, sliced"),
      ("Orange Glazed", "Chinese-American", "2|oranges, zest and juice; 2 tbsp|soy sauce; 1 tbsp|honey; 1 tsp|chili flakes; 2|spring onions, sliced"),
      ("Teriyaki", "Japanese", "4 tbsp|soy sauce; 3 tbsp|mirin; 1 tbsp|sugar; 1 tsp|ginger, grated; 200 g|green beans")]
for i, ((pn, ping, pm), (sn, cu, sing)) in enumerate(itertools.product(QP, QS)):
    if i % 2: continue
    ing = ping
    if pn == "Tofu": sing2 = sing.replace("2 tbsp|oyster sauce", "2 tbsp|hoisin sauce").replace("1 tbsp|fish sauce", "1 tbsp|soy sauce")
    else: sing2 = sing
    title = "%s %s Stir-Fry" % (sn, pn)
    R(Q, title, "Main", cu, 10, 12, 4, "Dinner, Main dish", ing + "; 1 tbsp|vegetable oil; 1 tsp|cornstarch|opt; " + sing2 + "; 300 g|rice, to serve",
      ["Start the rice. Mix the sauce ingredients (sauces, sweetener, citrus or nut butter) with 3 tbsp water",
       "Heat the oil in a wok or large pan over high heat and stir-fry the %s for %d minutes until browned and just cooked; lift out" % (pn.lower(), pm),
       "Stir-fry the vegetables, garlic, ginger or chili for 2 to 3 minutes until crisp-tender",
       "Return the %s, pour in the sauce and toss for a minute until glossy. Add any herbs and seeds and serve over rice" % pn.lower()])
